group = [61,63,86,114,140,188,251,329,339,359,517,656]
start, end = 18400, 36212
from collections import defaultdict
# events is available
ev = [tuple(e) for e in events if e[2] >= start and e[2] <= end]
# build node->contact->times
node_to_contacts = defaultdict(lambda: defaultdict(list))
for u,v,t in ev:
    node_to_contacts[u][v].append(t)
    node_to_contacts[v][u].append(t)
for a in list(node_to_contacts.keys()):
    for b in list(node_to_contacts[a].keys()):
        node_to_contacts[a][b].sort()
closures = []
for i,x in enumerate(group):
    for y in group[i+1:]:
        contacts_x = set(node_to_contacts[x].keys())
        contacts_y = set(node_to_contacts[y].keys())
        common = contacts_x & contacts_y
        for z in common:
            if z==x or z==y:
                continue
            for tx in node_to_contacts[x][z]:
                for ty in node_to_contacts[y][z]:
                    tshared = max(tx,ty)
                    # find any interaction between x and y at time between tshared and tshared+800
                    for u,v,t in ev:
                        if ((u==x and v==y) or (u==y and v==x)) and tshared <= t <= tshared+800:
                            closures.append({'pair':(x,y),'via':z,'tx':tx,'ty':ty,'tshared':tshared,'tclose':t})
closures.sort(key=lambda c:c['tclose'])
print('num_closures', len(closures))
for c in closures[:100]:
    print(c)
if closures:
    print('wave_finish_time', closures[-1]['tclose'])
    times = sorted({c['tclose'] for c in closures})
    print('unique_closure_times_count', len(times))
    print('first_last_times', times[0], times[-1])
else:
    print('no closures found')
closed_pairs = sorted({c['pair'] for c in closures})
print('closed_pairs_count', len(closed_pairs))
print('closed_pairs', closed_pairs)

